/** A job and the column it sits in. */
export interface JobAt {
  jobId: string
  column: JobColumn
}

/** The job a row is tied to, or null on the person. */
export function jobOf(row: Pick<MessageRow, JobColumn>): JobAt | null {
  for (const column of JOB_COLUMNS) {
    const id = row[column]
    if (id) return { jobId: id, column }
  }
  return null
}

/** The star among a contact's `contact_jobs` rows: where a new line from them lands. Null puts it on the person. */
export function defaultJob(rows: readonly (Pick<MessageRow, JobColumn> & { is_default: boolean })[]): JobAt | null {
  const star = rows.find((r) => r.is_default)
  return star ? jobOf(star) : null
}

const LINE_CHANNELS = ['text', 'call', 'missed', 'voicemail'] as const
const OPTOUT_LINES: readonly string[] = ['first', 'silence', 'held']
const DELIVERIES: readonly string[] = ['delivered', 'undelivered', 'failed']
const MAILBOX_SET: ReadonlySet<string> = new Set<Mailbox>(['team', 'bids'])

/**
 * A row as the kernels' line, with the revision the webhook read. Null for a row Quo did not write: no Quo id, or a
 * channel and direction no Quo event makes (a note, an email). Pictures are not kept on the row yet (cut 10).
 */
export function lineFromRow(row: MessageRow): { line: QuoLine; rev: number } | null {
  const channel = LINE_CHANNELS.find((c) => c === row.channel)
  const direction = row.direction === 'in' || row.direction === 'out' ? row.direction : null
  if (!row.quo_id || !channel || !direction) return null
  return {
    rev: row.quo_rev,
    line: {
      quoId: row.quo_id,
      contactId: row.contact_id,
      channelId: row.channel_id,
      jobId: jobOf(row)?.jobId ?? null,
      channel,
      direction,
      at: row.at,
      who: row.who_text,
      whoUserId: row.who_user_id,
      body: row.body,
      recordingUrl: row.recording_url,
      transcript: row.transcript,
      summary: row.summary,
      durationSeconds: row.duration_seconds,
      media: [],
      optoutLine: OPTOUT_LINES.includes(row.optout_line ?? '') ? (row.optout_line as OptoutRecord) : null,
      delivery: DELIVERIES.includes(row.delivery ?? '') ? (row.delivery as QuoDelivery) : null,
      mailbox: MAILBOX_SET.has(row.mailbox ?? '') ? (row.mailbox as Mailbox) : null,
    },
  }
}

/** The columns `quo_write_line` takes for a line, as jsonb. */
export type MessageColumns = Record<string, string | number | null>

/**
 * A line as the columns `quo_write_line` writes. Its job goes in the column it is known by: the row's own, or the
 * contact's star (`jobs`). A job the webhook cannot place is an error, never a guess.
 */
export function rowFromLine(line: QuoLine, jobs: readonly JobAt[]): { ok: true; columns: MessageColumns } | { ok: false; why: string } {
  const at = line.jobId ? jobs.find((j) => j.jobId === line.jobId) : undefined
  if (line.jobId && !at) return { ok: false, why: `no column is known for job ${line.jobId}` }
  return {
    ok: true,
    columns: {
      contact_id: line.contactId,
      channel_id: line.channelId,
      bid_id: at?.column === 'bid_id' ? at.jobId : null,
      project_id: at?.column === 'project_id' ? at.jobId : null,
      jobs_ledger_id: at?.column === 'jobs_ledger_id' ? at.jobId : null,
      channel: line.channel,
      direction: line.direction,
      who_user_id: line.whoUserId,
      who_text: line.who,
      at: line.at,
      body: line.body,
      optout_line: line.optoutLine,
      recording_url: line.recordingUrl,
      transcript: line.transcript,
      summary: line.summary,
      duration_seconds: line.durationSeconds,
      delivery: line.delivery,
      mailbox: line.mailbox,
    },
  }
}

/** Every kind a contact can be, so a kind added to `ContactKind` fails the typecheck here until it is read. */
const CONTACT_KINDS: Record<ContactKind, true> = { customer: true, trade: true, arch: true, lead: true, supply_house: true, candidate: true, sub: true, unknown: true }

/** A contact's kind as `quo_place_number` answers it: any of the seven kinds, else a number nobody has named. */
export function contactKindOf(raw: string | null | undefined): ContactKind {
  return raw && Object.prototype.hasOwnProperty.call(CONTACT_KINDS, raw) ? (raw as ContactKind) : 'unknown'
}

/** The words a line shows for a contact: what they are called, else their number. */
export function contactWords(contact: { name: string; goesBy: string | null; kind: ContactKind }, number: string): string {
  return firstName(contact) || phoneWords(number)
}

/**
 * Where Quo's seats are read from: the Settings row (`app_settings` `messages_quo_seats_v1`, Settings → Phone and
 * texts, v2.5335) once it names a seat, else the `QUO_SEATS` secret, which held them first. So the row and the
 * functions land in either order, and the secret can go once the row is filled.
 */
export function seatsSource(row: string | null | undefined, secret: string | undefined): string | undefined {
  return seatPairs(row ?? undefined).length > 0 ? (row ?? undefined) : secret
}

/**
 * Quo's seats (`{"US…": "<user id>"}`, from `seatsSource`) with the users' names. A seat whose user is not found, or
 * words that are not JSON, give nothing.
 */
export function quoSeats(raw: string | undefined, users: readonly { id: string; name: string | null }[]): QuoPlanContext['users'] {
  const out: Record<string, { userId: string; name: string }> = {}
  for (const [quoUserId, userId] of seatPairs(raw)) {
    const user = users.find((u) => u.id === userId)
    if (user) out[quoUserId] = { userId: user.id, name: user.name?.trim() || 'Someone' }
  }
  return out
}

/** The user ids the seats name, for the one read of their names. */
export function quoSeatUserIds(raw: string | undefined): string[] {
  return [...new Set(seatPairs(raw).map(([, userId]) => userId))]
}

function seatPairs(raw: string | undefined): Array<[string, string]> {
  let parsed: unknown
  try {
    parsed = raw ? JSON.parse(raw) : {}
  } catch {
    return []
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return []
  return Object.entries(parsed as Record<string, unknown>).filter((pair): pair is [string, string] => typeof pair[1] === 'string' && pair[1].trim() !== '')
}

/** The Quo user one of ours sends as, or null when they have no seat (Quo sends as the number's owner). */
export function seatOf(userId: string, seats: QuoPlanContext['users']): string | null {
  return Object.entries(seats).find(([, s]) => s.userId === userId)?.[0] ?? null
}

/** What the send window asks `quo-send` for: whose number, the words, the files as link lines, the hold, the tie. */
export interface QuoSendBody {
  contactId: string
  channelId: string
  body: string
  links: Array<{ text: string; link: string }>
  held: boolean
  tie: JobAt | null
}

const JOB_COLUMN_SET: ReadonlySet<string> = new Set(JOB_COLUMNS)

/** `quo-send`'s request, read; null when it is missing something. */
export function parseQuoSendBody(json: unknown): QuoSendBody | null {
  if (!json || typeof json !== 'object' || Array.isArray(json)) return null
  const o = json as Record<string, unknown>
  const text = (v: unknown) => (typeof v === 'string' && v.trim() ? v.trim() : null)
  const contactId = text(o.contactId)
  const channelId = text(o.channelId)
  const body = typeof o.body === 'string' ? o.body : null
  if (!contactId || !channelId || body === null) return null
  const links = (Array.isArray(o.links) ? o.links : [])
    .map((l) => (l && typeof l === 'object' ? (l as Record<string, unknown>) : null))
    .filter((l): l is Record<string, unknown> => l !== null && typeof l.text === 'string' && typeof l.link === 'string' && l.link.trim() !== '')
    .map((l) => ({ text: String(l.text), link: String(l.link).trim() }))
  const tieRaw = o.tie && typeof o.tie === 'object' ? (o.tie as Record<string, unknown>) : null
  const tieJob = tieRaw ? text(tieRaw.jobId) : null
  const tieColumn = tieRaw && typeof tieRaw.column === 'string' && JOB_COLUMN_SET.has(tieRaw.column) ? (tieRaw.column as JobColumn) : null
  if (tieRaw && (!tieJob || !tieColumn)) return null
  return { contactId, channelId, body, links, held: o.held === true, tie: tieJob && tieColumn ? { jobId: tieJob, column: tieColumn } : null }
}
